import { lazy } from 'react';
import { Coins as IcCoins, Target as IcTarget } from 'lucide-react';
import { TabHub } from '@/components/pulse-ui';

/**
 * Targets & Commission — hub page for the Sales menu.
 *
 * Generated by the 2026-09-16 information-architecture pass, which collapsed
 * 2 sidebar rows into this one destination. Each page below keeps its
 * NAV_ITEMS entry marked `inHub: 'SalesPerformance'`, so getSectionForPage() still
 * resolves it and every role gate behaves exactly as it did when each was its
 * own row. TabHub re-checks each tab with canRoleOpenPage() before drawing it.
 */
const SalesTargets = lazy(() => import('./SalesTargets'));
const CommissionManagement = lazy(() => import('./CommissionManagement'));

export const TABS = [
  { id: 'targets', label: 'Sales Targets', icon: IcTarget, page: 'SalesTargets', Component: SalesTargets },
  { id: 'commission', label: 'Commission', icon: IcCoins, page: 'CommissionManagement', Component: CommissionManagement },
];

export default function SalesPerformance({ setPage }) {
  return (
    <TabHub
      icon={IcTarget}
      eyebrow="Sales"
      title="Targets & Commission"
      subtitle="Quota setting, attainment and commission payout"
      tabs={TABS}
      setPage={setPage}
    />
  );
}
